CREATE OR REPLACE FUNCTION public.guard_profile_verification() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF pg_trigger_depth()>1 THEN RETURN NEW; END IF; IF auth.uid() IS NOT NULL AND NOT (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'verifier')) THEN IF TG_OP='INSERT' THEN IF NEW.kyc_status <> 'not_started' OR NEW.org_verified THEN RAISE EXCEPTION 'Verification is assigned by reviewers only'; END IF; ELSIF NEW.kyc_status IS DISTINCT FROM OLD.kyc_status OR NEW.org_verified IS DISTINCT FROM OLD.org_verified THEN RAISE EXCEPTION 'Verification is assigned by reviewers only'; END IF; END IF; RETURN NEW; END $$;